package com.kareem.lifeos;

import android.app.Activity;
import android.graphics.Typeface;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import java.text.DateFormat;
import java.util.Date;
import java.util.Locale;

public final class EvidenceDetailActivity extends Activity {
    private LifeDb db;private long eventId,loopId;private LifeDb.Event event;private LifeDb.Loop loop;private AttentionStore.Item attention;
    @Override public void onCreate(Bundle s){super.onCreate(s);db=new LifeDb(this);eventId=getIntent().getLongExtra("event_id",0);loopId=getIntent().getLongExtra("loop_id",0);event=db.eventById(eventId);loop=loopId>0?db.loopById(loopId):null;attention=AttentionStore.get(this).forEvent(eventId);render();}
    @Override protected void onDestroy(){db.close();super.onDestroy();}
    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(LifeOsUi.BG);LinearLayout head=LifeOsUi.topBar(this,"Evidence",false);Button back=LifeOsUi.button(this,"‹");back.setTextSize(20);back.setOnClickListener(v->finish());head.addView(back,0,new LinearLayout.LayoutParams(LifeOsUi.dp(this,46),LifeOsUi.dp(this,46)));root.addView(head);ScrollView sc=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,10),LifeOsUi.dp(this,16),LifeOsUi.dp(this,24));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));if(event==null){body.addView(LifeOsUi.text(this,"Original evidence is no longer available.",14,LifeOsUi.MUTED));setContentView(root);return;}TextView app=LifeOsUi.text(this,LifeDb.friendlyApp(event.app),12,LifeOsUi.GREEN);app.setTypeface(Typeface.DEFAULT,Typeface.BOLD);body.addView(app);String heading=heading();TextView h=LifeOsUi.text(this,heading,22,LifeOsUi.TEXT);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);h.setPadding(0,LifeOsUi.dp(this,6),0,LifeOsUi.dp(this,3));body.addView(h);body.addView(LifeOsUi.text(this,DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(new Date(event.at)),12,LifeOsUi.MUTED));LinearLayout why=LifeOsUi.card(this);LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(-1,-2);wp.setMargins(0,LifeOsUi.dp(this,16),0,0);why.setLayoutParams(wp);TextView wt=LifeOsUi.text(this,"WHY IT MATTERS",10,LifeOsUi.GREEN);wt.setTypeface(Typeface.DEFAULT,Typeface.BOLD);why.addView(wt);String reason=attention!=null&&!attention.reason.isEmpty()?attention.reason:loop!=null?reason(loop.kind):"This evidence is connected to something LifeOS surfaced for you.";TextView wr=LifeOsUi.text(this,UserFacingText.humanize(reason),14,LifeOsUi.TEXT);wr.setPadding(0,LifeOsUi.dp(this,8),0,0);why.addView(wr);if(attention!=null&&!attention.summary.isEmpty())why.addView(LifeOsUi.text(this,UserFacingText.humanize(attention.summary),12,LifeOsUi.MUTED));body.addView(why);LinearLayout original=LifeOsUi.card(this);TextView ot=LifeOsUi.text(this,"Original evidence",12,LifeOsUi.MUTED);ot.setTypeface(Typeface.DEFAULT,Typeface.BOLD);original.addView(ot);TextView raw=LifeOsUi.text(this,event.body==null?"":event.body,15,LifeOsUi.TEXT);raw.setPadding(0,LifeOsUi.dp(this,9),0,0);raw.setMaxLines(7);raw.setEllipsize(TextUtils.TruncateAt.END);raw.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG);original.addView(raw);if(event.body!=null&&event.body.length()>320){Button more=LifeOsUi.button(this,"Show full evidence");more.setOnClickListener(v->{boolean full=raw.getMaxLines()>50;raw.setMaxLines(full?7:Integer.MAX_VALUE);raw.setEllipsize(full?TextUtils.TruncateAt.END:null);more.setText(full?"Show full evidence":"Collapse evidence");});LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,42));mp.setMargins(0,LifeOsUi.dp(this,10),0,0);original.addView(more,mp);}body.addView(original);Button open=LifeOsUi.primary(this,SourceOpener.buttonLabel(this,eventId,event));open.setOnClickListener(v->{SourceOpener.Result r=SourceOpener.open(this,eventId,event);if(!r.opened||r.precision<SourceOpener.EXACT)Toast.makeText(this,r.message,Toast.LENGTH_LONG).show();});body.addView(open,new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,50)));boolean unresolved=(attention!=null&&attention.isOpen())||(loop!=null&&"open".equals(loop.status));if(unresolved){Button done=LifeOsUi.button(this,"Mark handled");LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,50));p.setMargins(0,LifeOsUi.dp(this,8),0,0);done.setOnClickListener(v->{AttentionStore.get(this).markHandled(eventId);db.getWritableDatabase().execSQL("UPDATE open_loops SET status='done' WHERE evidence_id=? AND status='open'",new Object[]{eventId});finish();});body.addView(done,p);}setContentView(root);}
    private String heading(){String t=event.title==null?"":event.title.trim(),low=t.toLowerCase(Locale.ROOT);boolean generic=t.isEmpty()||low.equals("info")||low.equals("notification")||low.equals("message")||low.equals("visible conversation");if(generic&&attention!=null&&!attention.summary.isEmpty())return UserFacingText.humanize(attention.summary);if(generic&&loop!=null&&!loop.title.isEmpty())return UserFacingText.humanize(loop.title);return t.isEmpty()?LifeDb.friendlyApp(event.app):t;}
    private static String reason(String kind){if("security".equals(kind))return "An account access or sign-in change may need verification.";if("financial_alert".equals(kind))return "A payment, card, or balance exception may need your attention.";if("deadline".equals(kind))return "This source contains a dated obligation that may still need action.";if("appointment".equals(kind))return "This source contains scheduling details you may need to act on.";if("commitment".equals(kind))return "A concrete commitment is still open.";return "A direct request appears to need action from you.";}
}
